  Q("7-AE7", 3, "No simulador, os raios de calor (infravermelho) que voltam da Terra ficam presos pela atmosfera. Os gases que causam esse efeito são, por exemplo:", ["gás carbônico, metano e vapor de água", "oxigênio e nitrogênio apenas", "hélio e neônio", "ozônio da estratosfera apenas"], "CO₂, metano (CH₄) e vapor de água estão entre os principais gases de efeito estufa.");
  Q("7-AE7", 3, "A queima de combustíveis fósseis (gasolina, diesel, carvão) intensifica o efeito estufa porque:", ["libera grande quantidade de gás carbônico na atmosfera", "retira gás carbônico do ar", "produz oxigênio", "diminui a temperatura"], "Mais CO₂ no ar retém mais calor, aumentando a temperatura média do planeta.");
  Q("7-AE7", 3, "A criação de gado em grande escala contribui para o efeito estufa porque os animais liberam:", ["metano durante a digestão", "oxigênio pela pele", "ozônio pelos pulmões", "nitrogênio puro"], "O metano é um gás de efeito estufa muito potente, produzido na digestão dos ruminantes.");
  Q("7-AE7", 3, "Uma consequência do aumento do efeito estufa é:", ["o derretimento de geleiras e a subida do nível do mar", "o resfriamento dos oceanos", "o aumento da camada de ozônio", "o fim das chuvas no planeta inteiro"], "O aquecimento global derrete o gelo e expande a água dos oceanos.");
  Q("7-AE7", 3, "Uma atitude que ajuda a reduzir a emissão de gases de efeito estufa é:", ["usar fontes de energia renováveis, como solar e eólica", "deixar luzes acesas o dia todo", "fazer queimadas", "usar mais o carro para trajetos curtos"], "Fontes renováveis emitem muito menos gás carbônico do que a queima de combustíveis fósseis.");
  Q("7-AE7", 3, "Um carro fechado e estacionado ao Sol fica muito quente por dentro. Isso se parece com o efeito estufa porque:", ["a luz entra pelo vidro, mas parte do calor fica presa lá dentro", "o carro produz calor sozinho", "o vidro esfria o ar", "a luz não consegue entrar"], "Assim como a atmosfera, o vidro deixa a luz passar e dificulta a saída do calor.");
  Q("7-AE7", 3, "As florestas ajudam a diminuir o efeito estufa porque:", ["absorvem gás carbônico do ar na fotossíntese", "produzem metano", "aquecem o ar", "liberam fumaça"], "As árvores retiram CO₂ da atmosfera e o armazenam em sua biomassa.");

  // 7-AE8 · Vírus, bactérias e fungos
  Q("7-AE8", 2, "Os vírus só conseguem se reproduzir dentro de células vivas. Por isso, dizemos que eles são:", ["parasitas obrigatórios", "seres unicelulares independentes", "plantas microscópicas", "fungos"], "Fora de uma célula, o vírus não se reproduz.");
  Q("7-AE8", 2, "Gripe, sarampo, COVID-19 e dengue são doenças causadas por:", ["vírus", "bactérias", "fungos", "vermes"], "Todas essas doenças são virais.");
  Q("7-AE8", 2, "Os antibióticos são remédios que combatem:", ["bactérias", "vírus", "todas as doenças", "alergias"], "Antibióticos não agem contra vírus; por isso não curam gripe.");
  Q("7-AE8", 2, "O fermento biológico usado para fazer pão contém leveduras, que são:", ["fungos", "bactérias", "vírus", "protozoários"], "As leveduras fermentam os açúcares e liberam gás carbônico, que faz a massa crescer.");
  Q("7-AE8", 2, "Nem toda bactéria é prejudicial. Um exemplo de bactéria útil são as que:", ["transformam o leite em iogurte", "causam tuberculose", "causam cárie", "estragam todos os alimentos"], "Lactobacilos fermentam o leite; outras bactérias vivem no intestino e nos ajudam.");
  Q("7-AE8", 2, "Lavar as mãos com água e sabão antes das refeições ajuda a:", ["remover microrganismos que podem causar doenças", "aumentar a quantidade de vírus", "impedir a digestão", "destruir as células da pele"], "A higiene das mãos é uma das formas mais simples de prevenir infecções.");
  Q("7-AE8", 2, "O bolor que aparece em um pão velho é formado por:", ["fungos", "bactérias", "vírus", "algas"], "O bolor é formado por hifas e esporos de fungos que decompõem o alimento.");

  // 7-AE10 · Biomas brasileiros
  Q("7-AE10", 3, "O bioma brasileiro com clima semiárido, chuvas escassas e plantas como o mandacaru e o xique-xique é a:", ["Caatinga", "Amazônia", "Mata Atlântica", "Pampa"], "A Caatinga é exclusiva do Brasil e suas plantas são adaptadas à seca.");
  Q("7-AE10", 3, "O bioma com árvores de troncos tortos, casca grossa e raízes profundas, típico do Brasil central, é o:", ["Cerrado", "Pantanal", "Pampa", "Amazônia"], "As raízes profundas buscam água no subsolo durante a estação seca do Cerrado.");
  Q("7-AE10", 3, "A maior planície alagável do mundo, com cheias periódicas, é o:", ["Pantanal", "Pampa", "Cerrado", "Caatinga"], "No Pantanal, as cheias e as secas definem a vida de plantas e animais.");
  Q("7-AE10", 3, "O bioma brasileiro mais devastado, que hoje tem apenas uma pequena parte da vegetação original, é a:", ["Mata Atlântica", "Amazônia", "Caatinga", "Pantanal"], "A Mata Atlântica ocupa a região mais populosa do país e foi muito desmatada.");
  Q("7-AE10", 3, "O Pampa, no Rio Grande do Sul, é caracterizado por:", ["campos com vegetação rasteira (gramíneas)", "floresta densa e úmida", "cactos e clima muito seco", "áreas alagadas o ano todo"], "O Pampa é formado por campos, usados também na criação de gado.");
  Q("7-AE10", 3, "Um incêndio destrói parte de um bioma. Uma consequência para os seres vivos dessa região é:", ["perda de abrigo e alimento, afetando as cadeias alimentares", "aumento da biodiversidade", "melhora do solo para sempre", "nenhuma mudança nos animais"], "A destruição do ambiente afeta plantas, animais e todas as relações entre eles.");

  // 7-AE11 · Vacinas e indicadores de saúde
  Q("7-AE11", 3, "As vacinas protegem o corpo porque:", ["estimulam o sistema imunológico a produzir defesas (anticorpos) antes do contato com a doença", "curam a doença depois que ela aparece", "matam todas as bactérias do corpo", "substituem a alimentação"], "A vacina ensina o organismo a reconhecer o agente causador e a se defender.");
  Q("7-AE11", 3, "Quando grande parte da população se vacina, até quem não pode tomar a vacina fica mais protegido. Isso acontece porque:", ["o agente causador da doença tem menos pessoas para infectar e circula menos", "a vacina passa pelo ar", "as doenças desaparecem sozinhas", "os vírus ficam mais fortes"], "É a chamada imunidade coletiva (ou de rebanho).");
  Q("7-AE11", 3, "Para saber quais vacinas uma criança já tomou e quais ainda faltam, devemos consultar a:", ["caderneta (carteira) de vacinação", "certidão de nascimento", "conta de luz", "receita de óculos"], "A caderneta registra as doses aplicadas e as próximas datas.");
  Q("7-AE11", 3, "O soro, diferente da vacina, é usado para:", ["tratar com anticorpos prontos, como em picadas de cobra", "prevenir doenças anos depois", "estimular o corpo a produzir anticorpos lentamente", "substituir a água do corpo"], "O soro já traz anticorpos prontos e age rápido; a vacina previne.");
  Q("7-AE11", 3, "O número de bebês que morrem antes de completar 1 ano, a cada mil nascidos vivos, é um indicador de saúde chamado:", ["taxa de mortalidade infantil", "expectativa de vida", "taxa de natalidade", "índice de massa corporal"], "Quanto menor a mortalidade infantil, melhores as condições de saúde e saneamento.");
  Q("7-AE11", 3, "A diminuição da vacinação em uma região pode provocar:", ["a volta de doenças que estavam controladas, como o sarampo", "o fim de todas as doenças", "o aumento da expectativa de vida", "a melhora da imunidade de todos"], "Com menos pessoas protegidas, doenças eliminadas podem voltar a circular.");
  Q("7-AE11", 3, "O acesso a água tratada e esgoto (saneamento básico) melhora os indicadores de saúde porque:", ["diminui doenças transmitidas pela água contaminada", "aumenta a poluição", "não tem relação com a saúde", "substitui as vacinas"], "Diarreias, hepatite A e outras doenças diminuem com saneamento.");
  Q("7-AE11", 3, "A expectativa de vida no Brasil aumentou nas últimas décadas. Um dos fatores que contribuíram para isso foi:", ["a ampliação da vacinação e do atendimento de saúde", "o aumento das queimadas", "a diminuição do saneamento", "o fim das escolas"], "Vacinas, saneamento e acesso à saúde aumentam o tempo médio de vida.");
  Q("7-AE11", 3, "Uma pessoa diz que não precisa se vacinar porque é saudável. A melhor resposta científica é:", ["a vacina prepara o corpo antes do contato com a doença e também protege as pessoas próximas", "pessoas saudáveis nunca ficam doentes", "a vacina só serve para idosos", "as vacinas causam as doenças que previnem"], "A vacinação protege individualmente e coletivamente.");

  /* ======================= 8º ANO ======================= */
  // 8-AE1 · Puberdade e sistema endócrino
  Q("8-AE1", 1, "As glândulas que produzem hormônios e os lançam diretamente no sangue fazem parte do sistema:", ["endócrino", "digestório", "respiratório", "esquelético"], "Os hormônios são mensageiros químicos levados pelo sangue.");
  Q("8-AE1", 1, "Na puberdade, os testículos passam a produzir mais testosterona, que causa, por exemplo:", ["engrossamento da voz e aparecimento de pelos no rosto", "menstruação", "desenvolvimento das mamas", "parada do crescimento logo aos 8 anos"], "A testosterona é responsável pelas características sexuais secundárias masculinas.");
  Q("8-AE1", 1, "Nas meninas, os hormônios produzidos pelos ovários, como o estrogênio, provocam:", ["desenvolvimento das mamas e início da menstruação", "engrossamento da voz", "barba", "queda dos dentes"], "Estrogênio e progesterona regulam o ciclo menstrual e as características femininas.");
  Q("8-AE1", 1, "A glândula localizada na base do cérebro que comanda outras glândulas e produz o hormônio do crescimento é a:", ["hipófise", "tireoide", "pâncreas", "suprarrenal"], "A hipófise é chamada de glândula \"mestra\" porque regula outras glândulas.");
  Q("8-AE1", 1, "O pâncreas produz a insulina, que tem a função de:", ["controlar a quantidade de açúcar (glicose) no sangue", "produzir lágrimas", "digerir proteínas no estômago", "aumentar os batimentos do coração"], "A falta de insulina pode causar diabetes.");
  Q("8-AE1", 1, "Em uma situação de susto ou perigo, o coração dispara por causa da adrenalina, produzida pelas glândulas:", ["suprarrenais", "salivares", "sudoríparas", "lacrimais"], "A adrenalina prepara o corpo para reagir rapidamente.");
  Q("8-AE1", 1, "Na adolescência, além das mudanças no corpo, são comuns mudanças de humor e de comportamento. Isso acontece porque:", ["os hormônios também agem no sistema nervoso", "o corpo para de crescer", "o sistema digestório muda de lugar", "os adolescentes deixam de ter hormônios"], "Os sistemas nervoso e endócrino trabalham juntos e influenciam emoções e comportamento.");
  Q("8-AE1", 1, "A menstruação acontece quando:", ["o óvulo não é fecundado e a parede interna do útero se descama", "o óvulo é fecundado", "o bebê nasce", "a pessoa come doces demais"], "Sem fecundação, o endométrio é eliminado — é o fluxo menstrual.");
  Q("8-AE1", 1, "A puberdade não acontece na mesma idade para todos. Isso significa que:", ["cada pessoa tem seu ritmo, e começar um pouco antes ou depois é normal", "quem começa depois está doente", "todos devem mudar no mesmo dia", "só meninos passam pela puberdade"], "O início da puberdade varia, geralmente entre 8 e 14 anos.");

  // 8-AE5 · Digestão e respiração
  Q("8-AE5", 1, "A digestão começa na boca, onde os dentes trituram o alimento e a saliva:", ["inicia a digestão do amido", "absorve os nutrientes", "produz bile", "transforma o alimento em fezes"], "A saliva tem uma enzima (amilase) que começa a quebrar o amido.");
  Q("8-AE5", 1, "A maior parte dos nutrientes é absorvida para o sangue no:", ["intestino delgado", "estômago", "esôfago", "intestino grosso"], "As vilosidades do intestino delgado aumentam a área de absorção.");
  Q("8-AE5", 1, "No estômago, o suco gástrico, que é bastante ácido, ajuda a:", ["digerir proteínas e eliminar muitos microrganismos", "absorver toda a água", "produzir oxigênio", "digerir somente gorduras"], "O suco gástrico contém ácido e enzimas que atuam sobre as proteínas.");
  Q("8-AE5", 1, "No intestino grosso ocorre principalmente:", ["a absorção de água e a formação das fezes", "a mastigação", "a troca de gases", "a produção de saliva"], "O intestino grosso reabsorve água e forma as fezes.");
  Q("8-AE5", 1, "Nos pulmões, a troca de gases acontece em pequenas bolsas chamadas:", ["alvéolos", "brônquios", "traqueias", "vilosidades"], "Nos alvéolos, o oxigênio passa para o sangue e o gás carbônico sai do sangue.");
  Q("8-AE5", 1, "Na inspiração, o ar entra nos pulmões porque o diafragma:", ["se contrai e desce, aumentando o espaço do tórax", "relaxa e sobe", "para de funcionar", "empurra o ar para fora"], "Com mais espaço no tórax, a pressão diminui e o ar entra.");
  Q("8-AE5", 1, "O caminho do ar ao entrar no corpo é:", ["nariz → faringe → laringe → traqueia → brônquios → pulmões", "boca → esôfago → estômago → pulmões", "pulmões → traqueia → nariz", "nariz → esôfago → intestino"], "O ar passa pelas vias respiratórias até os alvéolos dos pulmões.");
  Q("8-AE5", 1, "O fígado produz a bile, que ajuda na digestão das:", ["gorduras", "proteínas", "vitaminas", "fibras"], "A bile divide as gorduras em gotinhas, facilitando a ação das enzimas.");
  Q("8-AE5", 1, "Os sistemas digestório e respiratório trabalham juntos porque as células precisam de:", ["nutrientes e oxigênio para produzir energia na respiração celular", "apenas água", "apenas gás carbônico", "luz do Sol"], "Os nutrientes vêm da digestão e o oxigênio, da respiração; o sangue leva os dois às células.");
  Q("8-AE5", 1, "Fumar prejudica o sistema respiratório porque:", ["substâncias da fumaça danificam os alvéolos e as vias respiratórias", "aumenta a capacidade dos pulmões", "limpa os brônquios", "melhora a troca de gases"], "O cigarro está ligado a bronquite, enfisema e câncer de pulmão.");

  // 8-AE8 · Fases da Lua, eclipses e estações
  Q("8-AE8", 4, "Um eclipse solar acontece quando:", ["a Lua fica entre o Sol e a Terra e sua sombra atinge a Terra", "a Terra fica entre o Sol e a Lua", "o Sol fica entre a Terra e a Lua", "a Lua se afasta do Sol"], "No eclipse solar, a Lua bloqueia a luz do Sol para uma região da Terra.");
  Q("8-AE8", 4, "Um eclipse lunar só pode acontecer na fase de:", ["lua cheia", "lua nova", "quarto crescente", "quarto minguante"], "Na lua cheia, Sol, Terra e Lua podem ficar alinhados e a sombra da Terra cobre a Lua.");
  Q("8-AE8", 4, "As estações do ano acontecem principalmente porque:", ["o eixo da Terra é inclinado em relação ao plano da órbita", "a Terra se afasta muito do Sol no inverno", "a Lua bloqueia o Sol", "o Sol muda de tamanho"], "A inclinação faz cada hemisfério receber mais ou menos luz ao longo do ano.");
  Q("8-AE8", 4, "Quando é verão no hemisfério Sul (Brasil), no hemisfério Norte é:", ["inverno", "verão também", "primavera sempre", "não existe estação"], "Os hemisférios recebem luz de forma oposta por causa da inclinação do eixo.");
  Q("8-AE8", 4, "O ciclo completo das fases da Lua (de uma lua nova a outra) dura cerca de:", ["29 dias e meio", "24 horas", "365 dias", "7 dias"], "É o mês lunar, base de muitos calendários antigos.");

  // 8-AE9 · Clima e previsão do tempo
  Q("8-AE9", 4, "\"Hoje vai chover à tarde em São Paulo\" é uma informação sobre:", ["o tempo (condição da atmosfera em um momento)", "o clima (padrão de muitos anos)", "o relevo", "a hidrosfera apenas"], "Tempo é o estado momentâneo da atmosfera; clima é o padrão ao longo de décadas.");
  Q("8-AE9", 4, "O instrumento usado para medir a temperatura do ar é o:", ["termômetro", "barômetro", "pluviômetro", "anemômetro"], "O barômetro mede a pressão; o pluviômetro, a chuva; o anemômetro, o vento.");
  Q("8-AE9", 4, "O pluviômetro serve para medir:", ["a quantidade de chuva", "a velocidade do vento", "a umidade do solo", "a pressão do ar"], "A chuva é medida em milímetros (mm).");
  Q("8-AE9", 4, "Uma massa de ar frio que chega a uma região costuma provocar:", ["queda de temperatura e, muitas vezes, chuva na sua chegada", "aumento forte da temperatura", "o fim da atmosfera", "terremotos"], "As frentes frias trazem chuva e depois tempo mais frio e seco.");
  Q("8-AE9", 4, "As correntes marítimas influenciam o clima porque:", ["transportam águas quentes ou frias e alteram a temperatura e a umidade das regiões costeiras", "produzem terremotos", "não têm relação com o clima", "aumentam a camada de ozônio"], "Correntes quentes deixam o litoral mais úmido; frias tendem a deixá-lo mais seco.");
  Q("8-AE9", 4, "O fenômeno El Niño, o aquecimento anormal das águas do Oceano Pacífico, pode causar no Brasil:", ["secas no Nordeste e chuvas acima da média no Sul", "neve na Amazônia", "terremotos em São Paulo", "o fim das estações do ano"], "O El Niño altera a circulação atmosférica e o regime de chuvas.");
  Q("8-AE9", 4, "As previsões do tempo são feitas com dados de:", ["satélites, estações meteorológicas e modelos de computador", "observação apenas da Lua", "sorteio", "posição dos planetas"], "Os meteorologistas reúnem medições e simulações para prever o tempo.");

  // 8-AE10 · Mudanças climáticas
  Q("8-AE10", 4, "O aumento da temperatura média do planeta nas últimas décadas está ligado principalmente:", ["ao aumento de gases de efeito estufa emitidos por atividades humanas", "à diminuição da luz do Sol", "às fases da Lua", "aos terremotos"], "A queima de combustíveis fósseis e o desmatamento aumentaram o CO₂ no ar.");
  Q("8-AE10", 4, "Qual destas iniciativas ajuda a mitigar (diminuir) as mudanças climáticas?", ["Reflorestar áreas desmatadas", "Aumentar as queimadas", "Usar mais carvão para gerar energia", "Desperdiçar alimentos"], "As florestas retiram gás carbônico do ar.");
  Q("8-AE10", 4, "Uma possível consequência das mudanças climáticas para cidades litorâneas é:", ["a subida do nível do mar e o risco de inundações", "o aumento das praias", "o fim das marés", "o resfriamento das águas"], "O derretimento de geleiras e a expansão da água elevam o nível do mar.");
  Q("8-AE10", 4, "O Acordo de Paris, assinado por muitos países, tem como objetivo principal:", ["limitar o aumento da temperatura global reduzindo as emissões de gases", "aumentar a produção de petróleo", "acabar com as estações do ano", "proibir o uso de energia solar"], "Os países se comprometem a reduzir suas emissões de gases de efeito estufa.");
  Q("8-AE10", 4, "Eventos extremos, como secas mais longas e chuvas muito fortes, tendem a ficar mais frequentes com:", ["o aquecimento global", "a diminuição do efeito estufa", "a rotação da Terra", "a lua cheia"], "Um planeta mais quente tem mais energia na atmosfera, o que intensifica eventos extremos.");
  Q("8-AE10", 4, "Na escola, uma ação que contribui para diminuir as emissões de gases de efeito estufa é:", ["reduzir o desperdício de energia e de alimentos e separar o lixo para reciclagem", "deixar o ar-condicionado ligado com as janelas abertas", "queimar folhas secas no pátio", "imprimir tudo sem necessidade"], "Economizar energia e reduzir resíduos diminui as emissões indiretas.");
  Q("8-AE10", 4, "Os combustíveis renováveis, como o etanol da cana-de-açúcar, emitem menos gases de efeito estufa no total porque:", ["as plantas absorvem gás carbônico enquanto crescem", "não liberam nenhum gás ao queimar", "são extraídos do fundo do mar", "são feitos de petróleo"], "Parte do CO₂ liberado na queima foi retirado do ar pela própria plantação.");
  Q("8-AE10", 4, "O derretimento do gelo do Ártico afeta animais como o urso-polar porque:", ["eles perdem o ambiente onde caçam e se abrigam", "eles ganham mais alimento", "eles passam a viver no deserto", "não há nenhuma relação"], "As mudanças climáticas alteram os habitats e ameaçam espécies.");
  Q("8-AE10", 4, "Adaptação às mudanças climáticas significa:", ["preparar as cidades e as pessoas para os efeitos que já acontecem, como enchentes e ondas de calor", "aumentar as emissões de gases", "negar que o clima está mudando", "parar de medir a temperatura"], "Além de reduzir emissões, é preciso se adaptar: drenagem, áreas verdes, alertas de risco.");

  // 8-AE11 · Fontes e transformações de energia
  Q("8-AE11", 4, "Em uma usina hidrelétrica, a energia do movimento da água é transformada em:", ["energia elétrica", "energia nuclear", "energia química dos alimentos", "energia solar"], "A água gira as turbinas, que acionam geradores elétricos.");
  Q("8-AE11", 4, "Em uma lanterna de pilhas ligada, a sequência de transformações de energia é:", ["química → elétrica → luminosa (e um pouco de calor)", "luminosa → química → elétrica", "elétrica → química → sonora", "térmica → luminosa → química"], "A pilha guarda energia química, que vira elétrica no circuito e luz na lâmpada.");
  Q("8-AE11", 4, "Em um ventilador ligado na tomada, a principal transformação de energia é:", ["elétrica em energia de movimento (cinética)", "química em luminosa", "luminosa em elétrica", "térmica em química"], "O motor do ventilador transforma energia elétrica em movimento das pás.");
  Q("8-AE11", 4, "Um painel solar transforma:", ["energia luminosa do Sol em energia elétrica", "energia elétrica em luz solar", "energia dos ventos em calor", "energia química em movimento"], "As células fotovoltaicas convertem luz em eletricidade.");
  Q("8-AE11", 4, "Quando comemos, o corpo usa a energia química dos alimentos para:", ["manter as funções vitais, se movimentar e produzir calor", "produzir energia elétrica para a casa", "gerar luz como uma lâmpada", "nada, pois alimentos não têm energia"], "A energia química dos alimentos é liberada na respiração celular.");
  Q("8-AE11", 4, "Uma desvantagem das usinas termelétricas que queimam carvão ou óleo é que elas:", ["emitem gases poluentes e de efeito estufa", "não produzem energia", "dependem do vento", "só funcionam à noite"], "A queima de combustíveis fósseis polui o ar e intensifica o efeito estufa.");
  Q("8-AE11", 4, "Em toda transformação de energia, parte dela costuma se \"perder\" na forma de:", ["calor", "água", "luz da Lua", "massa"], "Por isso aparelhos esquentam; a energia não desaparece, mas parte vira calor não aproveitado.");

  // 8-AE12 · Circuitos elétricos
  Q("8-AE12", 4, "No simulador do circuito, a pilha tem a função de:", ["fornecer a energia que movimenta os elétrons pelo circuito", "acender a lâmpada sem fios", "interromper a corrente", "medir a temperatura"], "A pilha é a fonte de energia elétrica do circuito.");
  Q("8-AE12", 4, "Para que a lâmpada acenda, o circuito precisa estar:", ["fechado, formando um caminho completo para a corrente", "aberto, com o fio cortado", "sem pilha", "com o interruptor desligado"], "A corrente elétrica só circula em um caminho fechado.");
  Q("8-AE12", 4, "O interruptor (chave) em um circuito serve para:", ["abrir ou fechar o circuito, desligando ou ligando a corrente", "aumentar a energia da pilha", "transformar luz em eletricidade", "esquentar os fios"], "Desligar o interruptor abre o circuito e a corrente para.");
  Q("8-AE12", 4, "Os fios de circuitos são feitos de cobre e cobertos por plástico porque:", ["o cobre conduz bem a eletricidade e o plástico é isolante", "o cobre é isolante e o plástico conduz", "os dois são isolantes", "o plástico produz energia"], "Bons condutores deixam a corrente passar; isolantes protegem contra choques.");
  Q("8-AE12", 4, "Qual destes materiais é um bom condutor de eletricidade?", ["Alumínio", "Borracha", "Madeira seca", "Vidro"], "Os metais, em geral, são bons condutores.");
  Q("8-AE12", 4, "Em um circuito em série com duas lâmpadas, se uma queimar:", ["a outra também apaga, porque o caminho da corrente é interrompido", "a outra fica mais forte", "nada acontece com a outra", "a pilha recarrega"], "Em série há um único caminho; se ele abre, toda a corrente para.");
  Q("8-AE12", 4, "Nas casas, as lâmpadas são ligadas em paralelo. A vantagem disso é que:", ["se uma lâmpada queimar, as outras continuam funcionando", "todas apagam juntas", "a conta de luz zera", "não é preciso interruptor"], "No circuito em paralelo cada aparelho tem seu próprio caminho.");
  Q("8-AE12", 4, "Mexer em tomadas com as mãos molhadas é perigoso porque:", ["a água com sais minerais conduz eletricidade e aumenta o risco de choque", "a água é um isolante perfeito", "a tomada esfria", "a água desliga a energia"], "A água comum conduz corrente e facilita o choque elétrico.");

  // 8-AE13 · Consumo de energia
  Q("8-AE13", 4, "No simulador de consumo, o chuveiro elétrico aparece entre os maiores gastos porque:", ["tem alta potência para aquecer a água", "fica ligado o dia inteiro", "não usa eletricidade", "é o menor aparelho da casa"], "Aparelhos que geram calor, como chuveiro e ferro, costumam ter grande potência.");
  Q("8-AE13", 4, "O consumo de energia de um aparelho depende de:", ["sua potência e do tempo em que fica ligado", "apenas da sua cor", "apenas do tamanho da tomada", "da marca da lâmpada da sala"], "Consumo (kWh) = potência (kW) × tempo de uso (h).");
  Q("8-AE13", 4, "A unidade usada na conta de luz para medir o consumo de energia elétrica é o:", ["quilowatt-hora (kWh)", "metro (m)", "litro (L)", "grau Celsius (°C)"], "1 kWh é a energia usada por um aparelho de 1000 W ligado durante 1 hora.");
  Q("8-AE13", 4, "Uma lâmpada de 10 W fica acesa 5 horas por dia. Quanto ela consome por dia?", ["50 Wh", "15 Wh", "2 Wh", "500 Wh"], "10 W × 5 h = 50 Wh (0,05 kWh).");
  Q("8-AE13", 4, "Trocar lâmpadas incandescentes por lâmpadas de LED economiza energia porque o LED:", ["produz a mesma luz com menor potência e esquenta menos", "não precisa de eletricidade", "fica sempre desligado", "consome mais, porém dura menos"], "O LED transforma mais energia em luz e menos em calor.");
  Q("8-AE13", 4, "O selo Procel na etiqueta de um eletrodoméstico indica que ele:", ["é mais eficiente e consome menos energia", "é mais barato de comprar", "foi feito no exterior", "não pode ser usado em casa"], "O selo e a etiqueta (faixa A) ajudam a escolher aparelhos econômicos.");
  Q("8-AE13", 4, "Uma atitude que reduz o consumo de energia em casa é:", ["tomar banhos mais curtos e não deixar a geladeira aberta", "deixar a TV ligada sem ninguém assistindo", "abrir a geladeira várias vezes", "usar o chuveiro na temperatura máxima no verão"], "Pequenos hábitos reduzem a conta de luz e o impacto ambiental.");
  Q("8-AE13", 4, "Aparelhos em modo de espera (stand-by), com a luzinha acesa, também consomem energia. Para economizar, o ideal é:", ["desligá-los da tomada quando não forem usados por muito tempo", "deixar sempre em stand-by", "aumentar o volume", "ligar mais aparelhos"], "O consumo em stand-by é pequeno, mas somado ao longo do mês faz diferença.");
  Q("8-AE13", 4, "Economizar energia elétrica também ajuda o meio ambiente porque:", ["diminui a necessidade de construir usinas e de queimar combustíveis", "aumenta as emissões de gases", "não tem relação com a natureza", "gasta mais água"], "Toda forma de gerar energia causa algum impacto ambiental.");

  /* ======================= 9º ANO ======================= */
  // 9-AE2 · Modelos atômicos
  Q("9-AE2", 1, "No modelo atômico de Dalton, o átomo era imaginado como:", ["uma esfera maciça e indivisível, como uma bola de bilhar", "um pudim com passas", "um sistema com núcleo e eletrosfera", "uma onda de luz"], "Dalton propôs átomos maciços e indivisíveis.");
  Q("9-AE2", 1, "Thomson descobriu o elétron e propôs um modelo em que o átomo era:", ["uma esfera positiva com elétrons espalhados (pudim de passas)", "maciço e indivisível", "formado só por nêutrons", "vazio, sem partículas"], "No modelo de Thomson, as cargas negativas ficam incrustadas na massa positiva.");
  Q("9-AE2", 1, "Na experiência de Rutherford, a maioria das partículas atravessou a folha de ouro. Isso mostrou que o átomo:", ["é formado em grande parte por espaço vazio, com um núcleo pequeno e denso", "é maciço", "não tem carga elétrica", "é maior que a folha de ouro"], "Rutherford concluiu que há um núcleo muito pequeno e uma grande eletrosfera.");
  Q("9-AE2", 1, "No modelo do átomo, os prótons (carga positiva) e os nêutrons (sem carga) ficam no:", ["núcleo", "eletrosfera", "espaço entre os átomos", "elétron"], "Os elétrons, negativos, ficam na eletrosfera, ao redor do núcleo.");
  Q("9-AE2", 1, "O que diferencia um elemento químico de outro é o:", ["número de prótons (número atômico)", "número de nêutrons apenas", "tamanho da amostra", "estado físico"], "Todo átomo de carbono tem 6 prótons; todo átomo de oxigênio tem 8.");
  Q("9-AE2", 1, "No modelo de Bohr, os elétrons:", ["giram em camadas (níveis de energia) definidas ao redor do núcleo", "ficam parados dentro do núcleo", "não existem", "ficam espalhados numa massa positiva"], "Bohr propôs camadas eletrônicas com energias definidas.");
  Q("9-AE2", 1, "Na tabela periódica, os elementos estão organizados em ordem crescente de:", ["número atômico", "data de descoberta", "cor", "nome em ordem alfabética"], "A tabela organiza os elementos pelo número de prótons e agrupa propriedades semelhantes.");
  Q("9-AE2", 1, "Os modelos atômicos mudaram ao longo da história porque:", ["novas experiências trouxeram evidências que os modelos anteriores não explicavam", "os cientistas mudavam de opinião sem motivo", "os átomos mudaram de forma", "o primeiro modelo estava certo e os outros são errados"], "A ciência revisa seus modelos diante de novas evidências.");

  // 9-AE3 · Estados físicos da matéria
  Q("9-AE3", 1, "A passagem da água do estado sólido (gelo) para o líquido chama-se:", ["fusão", "solidificação", "condensação", "ebulição"], "Fusão: sólido → líquido.");
  Q("9-AE3", 1, "Quando o vapor de água encontra uma superfície fria e forma gotinhas, como no espelho do banheiro, ocorre a:", ["condensação", "fusão", "sublimação", "solidificação"], "Condensação (ou liquefação): gasoso → líquido.");
  Q("9-AE3", 1, "A água ferve a 100 °C ao nível do mar. Essa temperatura é o ponto de:", ["ebulição", "fusão", "solidificação", "congelamento"], "No ponto de ebulição, o líquido passa rapidamente para o estado gasoso.");
  Q("9-AE3", 1, "No estado sólido, as partículas de uma substância:", ["ficam bem próximas e organizadas, apenas vibrando", "se movem livremente e muito afastadas", "não existem", "estão sempre em ebulição"], "Por isso o sólido tem forma e volume definidos.");
  Q("9-AE3", 1, "No estado gasoso, as partículas:", ["ficam afastadas e se movimentam muito, ocupando todo o recipiente", "ficam presas em posições fixas", "ficam paradas", "formam cristais"], "Gases não têm forma nem volume próprios.");
  Q("9-AE3", 1, "A naftalina e o gelo-seco passam do estado sólido direto para o gasoso. Essa mudança é a:", ["sublimação", "fusão", "condensação", "evaporação"], "Sublimação: sólido → gasoso, sem passar pelo líquido.");
  Q("9-AE3", 1, "Ao aquecer uma substância, suas partículas:", ["se agitam mais e tendem a se afastar", "ficam mais lentas", "diminuem de número", "se transformam em outras substâncias"], "Mais energia térmica = mais agitação das partículas.");
  Q("9-AE3", 1, "A roupa seca no varal mesmo sem a água ferver. Isso acontece por:", ["evaporação, que ocorre em temperaturas abaixo da ebulição", "fusão", "solidificação", "condensação"], "A evaporação é lenta e ocorre na superfície do líquido.");
  Q("9-AE3", 1, "O ferro derrete a cerca de 1538 °C e a água a 0 °C. Isso mostra que:", ["cada substância tem seu próprio ponto de fusão", "todas as substâncias derretem na mesma temperatura", "o ferro não pode derreter", "a água é um metal"], "Os pontos de fusão e de ebulição ajudam a identificar substâncias.");

  // 9-AE9 · Lamarck e Darwin
  Q("9-AE9", 4, "Segundo Lamarck, as girafas teriam pescoço comprido porque:", ["esticavam o pescoço para alcançar as folhas, e essa característica seria passada aos filhotes", "as de pescoço comprido sobreviviam mais e deixavam mais filhotes", "foram criadas assim e nunca mudaram", "comiam mais"], "Lamarck propôs a lei do uso e desuso e a herança de características adquiridas.");
  Q("9-AE9", 4, "Segundo Darwin, as girafas de pescoço mais comprido:", ["conseguiam mais alimento, sobreviviam e deixavam mais descendentes", "esticaram o pescoço durante a vida", "surgiram de repente", "eram todas iguais"], "É a seleção natural: os mais adaptados ao ambiente deixam mais descendentes.");
  Q("9-AE9", 4, "Hoje sabemos que uma característica adquirida durante a vida, como músculos fortes pela academia:", ["não é passada aos filhos pelos genes", "é sempre herdada pelos filhos", "muda o DNA de todas as células reprodutivas", "faz os filhos nascerem fortes"], "Características adquiridas não alteram o material genético que é herdado.");
  Q("9-AE9", 4, "Darwin observou animais nas Ilhas Galápagos, como tentilhões com bicos de formatos diferentes. Ele relacionou isso:", ["ao tipo de alimento disponível em cada ilha", "à cor das penas", "à vontade das aves", "à posição dos planetas"], "Os bicos estavam adaptados aos alimentos de cada ambiente.");
  Q("9-AE9", 4, "Na seleção natural, o \"mais apto\" é o indivíduo que:", ["tem características que aumentam sua chance de sobreviver e se reproduzir naquele ambiente", "é sempre o maior e mais forte", "vive mais tempo, mesmo sem filhos", "nunca fica doente"], "Aptidão está ligada à sobrevivência e à reprodução no ambiente.");
  Q("9-AE9", 4, "Uma ideia em comum entre Lamarck e Darwin é que:", ["as espécies mudam (evoluem) ao longo do tempo", "as espécies nunca mudam", "o uso de um órgão define os genes", "todos os seres vivos são iguais"], "Os dois defendiam a evolução, mas explicaram seus mecanismos de forma diferente.");
  Q("9-AE9", 4, "Hoje, as ideias de Darwin são complementadas pela genética, que explica:", ["como surgem as variações (mutações) e como elas passam de pais para filhos", "que a evolução não existe", "que as girafas esticam o pescoço", "que o ambiente não influencia os seres vivos"], "A união da seleção natural com a genética é a teoria sintética da evolução.");
  Q("9-AE9", 4, "Darwin publicou suas ideias no livro \"A Origem das Espécies\", em:", ["1859", "1500", "1969", "2000"], "A obra de 1859 é um marco da Biologia.");

  // 9-AE10 · Evolução e biodiversidade
  Q("9-AE10", 4, "No simulador, as mariposas claras foram mais caçadas quando o tronco ficou escuro (fuligem). Com o tempo, a população passou a ter mais mariposas:", ["escuras, porque ficavam camufladas e sobreviviam mais", "claras, porque eram mais fortes", "transparentes", "de todas as cores igualmente"], "É um exemplo clássico de seleção natural: o ambiente favoreceu as escuras.");
  Q("9-AE10", 4, "A semelhança entre o DNA de humanos e chimpanzés é muito grande. Para a evolução, isso indica que:", ["as duas espécies têm um ancestral comum relativamente recente", "os humanos vieram diretamente dos chimpanzés atuais", "o DNA não tem relação com parentesco", "todas as espécies têm DNA idêntico"], "Quanto mais parecido o DNA, mais recente é o ancestral comum entre as espécies.");
  Q("9-AE10", 4, "Bactérias resistentes a antibióticos se espalham quando o remédio é usado de forma errada porque:", ["o antibiótico elimina as sensíveis e as resistentes sobrevivem e se multiplicam", "o antibiótico cria bactérias novas", "as bactérias aprendem a resistir", "o remédio fortalece todas as bactérias"], "É seleção natural acontecendo rapidamente.");
  Q("9-AE10", 4, "O braço humano, a asa do morcego e a nadadeira da baleia têm ossos parecidos. Isso indica que esses animais:", ["têm um ancestral comum", "não têm nenhum parentesco", "foram feitos para a mesma função", "vivem no mesmo ambiente"], "São órgãos homólogos: mesma origem, funções diferentes.");
  Q("9-AE10", 4, "Biodiversidade é:", ["a variedade de seres vivos e de ambientes de uma região ou do planeta", "o número de pessoas de uma cidade", "a quantidade de rochas", "o tipo de clima"], "Inclui a diversidade de espécies, de genes e de ecossistemas.");
  Q("9-AE10", 4, "Uma espécie que só existe em determinado lugar, como o mico-leão-dourado na Mata Atlântica, é chamada de:", ["endêmica", "exótica", "extinta", "invasora"], "Espécies endêmicas são exclusivas de uma região.");
  Q("9-AE10", 4, "A variação entre indivíduos de uma mesma espécie é importante para a evolução porque:", ["oferece diferenças sobre as quais a seleção natural pode agir", "impede a reprodução", "faz todos ficarem iguais", "não tem importância"], "Sem variação, não há o que ser selecionado.");
  Q("9-AE10", 4, "Quando uma população fica isolada por muito tempo (por um rio ou uma montanha), ela pode:", ["acumular diferenças e originar uma nova espécie", "desaparecer imediatamente", "voltar a ser igual às outras", "parar de se reproduzir"], "O isolamento geográfico é um caminho para a formação de novas espécies (especiação).");

  // 9-AE11 · Problemas ambientais e Unidades de Conservação
  Q("9-AE11", 4, "As Unidades de Conservação, como parques nacionais e reservas, servem para:", ["proteger a biodiversidade, os recursos naturais e as paisagens", "construir indústrias", "aumentar o desmatamento", "criar lixões"], "São áreas protegidas por lei para conservar a natureza.");
  Q("9-AE11", 4, "Bacia hidrográfica é:", ["a área drenada por um rio principal e seus afluentes", "uma bacia de lavar roupas", "o fundo do oceano", "um tipo de rocha"], "Tudo que acontece na bacia (desmatamento, esgoto) afeta seus rios.");
  Q("9-AE11", 4, "A mata ciliar, que cresce nas margens dos rios, é importante porque:", ["protege o rio contra a erosão e o assoreamento", "aumenta a poluição", "seca o rio", "não tem função"], "Sem a mata ciliar, a terra das margens cai no rio e o deixa raso.");
  Q("9-AE11", 4, "Os \"3 Rs\" do consumo consciente são:", ["reduzir, reutilizar e reciclar", "remover, rasgar e repetir", "rir, recordar e reclamar", "regar, roçar e replantar"], "Reduzir vem primeiro: o melhor resíduo é aquele que não é gerado.");
  Q("9-AE11", 4, "O despejo de esgoto sem tratamento nos rios provoca:", ["a diminuição do oxigênio da água e a morte de peixes", "a limpeza do rio", "o aumento da água potável", "nenhum efeito"], "A matéria orgânica do esgoto consome oxigênio ao ser decomposta.");
  Q("9-AE11", 4, "Uma iniciativa da comunidade escolar para enfrentar problemas ambientais pode ser:", ["criar uma horta e um ponto de coleta seletiva na escola", "jogar lixo no córrego", "cortar as árvores do pátio", "desperdiçar água nas torneiras"], "Ações locais educam e reduzem o impacto ambiental.");
  Q("9-AE11", 4, "O plástico descartado de forma errada é um grande problema nos oceanos porque:", ["demora centenas de anos para se decompor e pode ser ingerido pelos animais", "se transforma em alimento", "limpa a água", "desaparece em poucos dias"], "Microplásticos chegam às cadeias alimentares, inclusive à nossa.");
  Q("9-AE11", 4, "Um desmatamento perto das nascentes de um rio pode causar:", ["diminuição da água disponível e piora da qualidade da água", "aumento das nascentes", "mais peixes no rio", "fim da erosão"], "A vegetação protege as nascentes e ajuda a água da chuva a infiltrar no solo.");

  // 9-AE12 · Sistema Solar
  Q("9-AE12", 2, "O planeta mais próximo do Sol é:", ["Mercúrio", "Vênus", "Terra", "Marte"], "A ordem é: Mercúrio, Vênus, Terra, Marte, Júpiter, Saturno, Urano e Netuno.");
  Q("9-AE12", 2, "O maior planeta do Sistema Solar, um gigante gasoso com uma grande mancha vermelha, é:", ["Júpiter", "Saturno", "Netuno", "Terra"], "A Grande Mancha Vermelha é uma tempestade gigante em Júpiter.");
  Q("9-AE12", 2, "Os planetas rochosos (telúricos) do Sistema Solar são:", ["Mercúrio, Vênus, Terra e Marte", "Júpiter, Saturno, Urano e Netuno", "apenas a Terra", "Saturno e Marte"], "Os quatro planetas internos são rochosos; os externos são gigantes gasosos e gelados.");
  Q("9-AE12", 2, "O modelo heliocêntrico, defendido por Copérnico e Galileu, afirma que:", ["os planetas, incluindo a Terra, giram ao redor do Sol", "o Sol gira ao redor da Terra", "a Terra é plana", "a Lua é o centro do Universo"], "Hélio = Sol. No geocêntrico, a Terra ficaria no centro.");
  Q("9-AE12", 2, "O cinturão de asteroides fica entre as órbitas de:", ["Marte e Júpiter", "Terra e Vênus", "Saturno e Urano", "Mercúrio e o Sol"], "É uma faixa com milhões de corpos rochosos.");
  Q("9-AE12", 2, "O Sistema Solar está localizado em uma galáxia chamada:", ["Via Láctea", "Andrômeda", "Nuvem de Magalhães", "Órion"], "A Via Láctea tem bilhões de estrelas; o Sol é uma delas.");

  // 9-AE13 · Vida fora da Terra
  Q("9-AE13", 2, "Para que seres humanos sobrevivam em Marte, seria necessário levar ou produzir, principalmente:", ["oxigênio, água, alimento e proteção contra radiação e frio", "apenas roupas de verão", "somente combustível", "nada, pois Marte é igual à Terra"], "Marte tem atmosfera muito fina de CO₂, é muito frio e recebe muita radiação.");
  Q("9-AE13", 2, "Os cientistas procuram água líquida em outros planetas e luas porque:", ["a água líquida é essencial para a vida como conhecemos", "a água é combustível de foguetes", "água deixa os planetas mais bonitos", "não há relação com a vida"], "Onde há água líquida, pode haver condições para a vida.");
  Q("9-AE13", 2, "A Estação Espacial Internacional (ISS) é importante porque:", ["permite pesquisas sobre como o corpo humano e outros seres reagem a viver no espaço", "fica na superfície da Lua", "é um satélite natural", "serve apenas para turismo"], "Os astronautas estudam os efeitos da microgravidade, entre outros temas.");
  Q("9-AE13", 2, "A zona habitável de uma estrela é a região onde:", ["a temperatura permite que exista água líquida na superfície de um planeta", "não há planetas", "a estrela é mais fria", "existem apenas asteroides"], "A Terra está na zona habitável do Sol.");
  Q("9-AE13", 2, "Um dos efeitos de passar muitos meses em microgravidade no corpo dos astronautas é:", ["perda de massa óssea e muscular", "aumento dos ossos", "crescimento de novos dentes", "melhora da visão em todos os casos"], "Sem o peso para sustentar, ossos e músculos enfraquecem; por isso os astronautas se exercitam.");
  Q("9-AE13", 2, "Planetas que giram ao redor de outras estrelas, fora do Sistema Solar, são chamados de:", ["exoplanetas", "asteroides", "cometas", "satélites naturais"], "Já foram descobertos milhares de exoplanetas.");
  Q("9-AE13", 2, "Os satélites artificiais que giram em torno da Terra são usados, por exemplo, para:", ["comunicação, GPS e previsão do tempo", "produzir oxigênio", "iluminar a noite", "provocar marés"], "A exploração espacial traz benefícios para o dia a dia.");
  Q("9-AE13", 2, "Viajar até outra estrela ainda é impossível para os seres humanos principalmente porque:", ["as distâncias são enormes e levariam milhares de anos com a tecnologia atual", "as estrelas são muito pequenas", "as naves são rápidas demais", "não existem outras estrelas"], "A estrela mais próxima do Sol fica a mais de 4 anos-luz.");
  Q("9-AE13", 2, "Antes de enviar pessoas a outros planetas, as agências espaciais enviam robôs (sondas e jipes) porque:", ["eles exploram ambientes perigosos sem arriscar vidas humanas", "robôs não precisam de energia", "pessoas não podem estudar ciência", "os robôs são mais baratos que um lápis"], "Jipes como o Perseverance estudam Marte e procuram sinais de vida antiga.");

